+            return AVERROR(ENOMEM);
+        temp = av_fast_realloc(ifd->entries, &ifd->size, required_size);
+        if (!temp)
+            return AVERROR(ENOMEM);
+        ifd->entries = temp;
+        entry = &ifd->entries[ifd->count++];
+    }
