+#include "proresdsp.h"
+
+typedef struct TileContext {
+    GetByteContext gb;
+    unsigned x, y;
+} TileContext;
+
+typedef struct ProResRAWContext {
+    ProresDSPContext prodsp;
+    BlockDSPContext  bdsp;
+
+    TileContext *tiles;
+    unsigned int tiles_size;
+    int nb_tiles;
+    int tw, th;
+    int nb_tw, nb_th;
+
+    enum AVPixelFormat pix_fmt;
+    AVFrame *frame;
+    void *hwaccel_picture_private;
+
