+/*
+ * Table 19 — Content of payload
+ */
+enum {
+    LCEVC_PAYLOAD_TYPE_SEQUENCE_CONFIG    = 0,
+    LCEVC_PAYLOAD_TYPE_GLOBAL_CONFIG      = 1,
+    LCEVC_PAYLOAD_TYPE_PICTURE_CONFIG     = 2,
