+                          0, 0, nb_bands, mps->nb_param_sets,
+                          mps->param_sets, extend_frame);
+
+    /* ICC */
+    err = ff_aac_ec_data_dec(gb, &mps->ott[MPS_ICC], MPS_ICC, 0, 0, nb_bands,
+                             indep, indep, mps->nb_param_sets);
+    if (err < 0) {
