+    memset(mps->smooth_mode, 0, sizeof(mps->smooth_mode));
+    if (ec->mps.high_rate_mode) {
+        for (int i = 0; i < mps->nb_param_sets; i++) {
+            mps->smooth_mode[i] = get_bits(gb, 2);
+            if (mps->smooth_mode[i] >= 2)
