+                    av_log(ac->avctx, AV_LOG_ERROR,
+                           "Error parsing TSD reshape data!\n");
+                    return err;
+                }
+            }
+        }
+    }
+
+    /* TSD data */
+    if (mps->tsd_enable) {
+        mps->tsd_num_tr_slots = get_bits(gb, param_slot_bits - 1);
+        int tsd_pos[64];
+        decode_tsd(gb, tsd_pos, mps->tsd_num_tr_slots, nb_time_slots);
