new file mode 100644
index 0000000000..7fea6208b4
--- /dev/null
+++ b/libavcodec/prores_raw.c
@@ -0,0 +1,531 @@
+/*
+ * ProRes RAW decoder
+ * Copyright (c) 2023-2025 Paul B Mahol
+ * Copyright (c) 2025 Lynne
+ *
