+        int tsd_pos[64];
+        decode_tsd(gb, tsd_pos, mps->tsd_num_tr_slots, nb_time_slots);
+        for (int i = 0; i < nb_time_slots; i++) {
+            mps->tsd_phase_data[i] = 0;
+            if (tsd_pos[i])
+                mps->tsd_phase_data[i] = get_bits(gb, 3);
