+
+enum AACMPSDataType {
+    MPS_CLD = 0,
+    MPS_ICC,
+    MPS_IPD,
+
+    MPS_ELE_NB,
+};
+
+typedef struct AACMPSLosslessData {
+    int16_t data[MPS_MAX_PARAM_SETS][MPS_MAX_PARAM_BANDS];
+    int16_t last_data[MPS_MAX_PARAM_BANDS];
