+    bool coarse_quant[MPS_MAX_PARAM_SETS];
+    int16_t freq_res[MPS_MAX_PARAM_SETS];
+    int16_t coarse_quant_no[MPS_MAX_PARAM_SETS];
+
+    bool quant_coarse_prev;
+} AACMPSLosslessData;
