+                          int default_value, int start_band, int stop_band,
+                          int nb_param_sets, const int *param_set_idx,
+                          int extend_frame);
+
+int ff_aac_huff_dec_reshape(GetBitContext *gb, int16_t *out_data,
+                            int nb_val);
+
+#endif /* AVCODEC_AAC_AACDEC_USAC_MPS212_H */

