diff --git a/libavcodec/aac.h b/libavcodec/aac.h
index 78026a5887..b77b6e7c18 100644
--- a/libavcodec/aac.h
+++ b/libavcodec/aac.h
@@ -34,10 +34,14 @@
 #define MAX_ELEM_ID 64

 #define TNS_MAX_ORDER 20
 #define MAX_LTP_LONG_SFB 40

